233	/* 串口读取线程：poll → read → 状态机 → 提取目标状态/距离
234	 * 2026-08-23 审查修复（FAIL1）：O_NONBLOCK 直 read 无数据时忙转烧 CPU，
235	 * 改 poll(POLLIN, 200ms) 带超时等待——无数据时线程休眠，不空转。 */
236	static void *ld2410b_reader(void *arg)
237	{
238	  int      fd = (int)(intptr_t)arg;
239	  uint8_t  buf[64];
240	  uint8_t  frame[FRAME_MAX_LEN];
241	  int      fpos = 0;
242	  int      flen = 0;
243	  int      st   = ST_WAIT_HDR;
244	  int      last_report_ts = 0;
245	  struct pollfd pfd;
246	
247	  pfd.fd     = fd;
248	  pfd.events = POLLIN;
249	
250	  while (g_ld2410b_run)
251	    {
252	      int pr = poll(&pfd, 1, 200);
253	      if (pr <= 0)
254	        continue;                    /* 超时/无数据：正常休眠重试 */
255	
256	      ssize_t n = read(fd, buf, sizeof(buf));
257	      if (n > 0)
258	        g_ld2410b_rx_bytes += n;       /* 调试：累计收到字节数 */
259	
260	      /* 2026-08-26 调试：每 5s 无条件打印一次收字节/有效帧数——
261	       *  零信号时也打印 rx=0B，可区分「线程活着但无信号」vs「有信号」；
262	       *  回环测试（短接 TX/RX 后 echo /dev/uart3）时 rx 应增长 */
263	      if (lv_tick_get() - last_report_ts > 5000)
264	        {
265	          last_report_ts = lv_tick_get();
266	          LV_LOG_USER("[ld2410b] rx=%uB frames=%u", g_ld2410b_rx_bytes,
267	                      g_ld2410b_frame_cnt);
268	        }
269	
270	      if (n <= 0)
271	        continue;                    /* 无数据可读（非阻塞，直接重试） */
272	
273	      for (ssize_t i = 0; i < n; i++)
274	        {
275	          uint8_t b = buf[i];
276	
277	          switch (st)
278	            {
279	            case ST_WAIT_HDR:
280	              if (b == FRAME_HDR0) st = ST_HDR1;
281	              break;
282	            case ST_HDR1:
283	              st = (b == FRAME_HDR1) ? ST_HDR2 : ST_WAIT_HDR;
284	              break;
285	            case ST_HDR2:
286	              st = (b == FRAME_HDR2) ? ST_HDR3 : ST_WAIT_HDR;
287	              break;
288	            case ST_HDR3:
289	              st = (b == FRAME_HDR3) ? ST_LEN_LO : ST_WAIT_HDR;
290	              break;
291	            case ST_LEN_LO:
292	              flen = b;
293	              st   = ST_LEN_HI;
294	              break;
295	            case ST_LEN_HI:
296	              flen |= (b << 8);
297	              if (flen < DATA_LEN_BASIC || flen > FRAME_MAX_LEN)
298	                {
299	                  st = ST_WAIT_HDR;  /* 长度非法，重新找头 */
300	                }
301	              else
302	                {
303	                  fpos = 0;
304	                  st   = ST_DATA;
305	                }
306	              break;
307	            case ST_DATA:
308	              frame[fpos++] = b;
309	              if (fpos >= flen)
310	                st = ST_TAIL0;
311	              break;
312	            case ST_TAIL0:
313	              st = (b == FRAME_TAIL0) ? ST_TAIL1 : ST_WAIT_HDR;
314	              break;
315	            case ST_TAIL1:
316	              st = (b == FRAME_TAIL1) ? ST_TAIL2 : ST_WAIT_HDR;
317	              break;
318	            case ST_TAIL2:
319	              st = (b == FRAME_TAIL2) ? ST_TAIL3 : ST_WAIT_HDR;
320	              break;
321	            case ST_TAIL3:
322	              if (b == FRAME_TAIL3)
323	                {
324	                  ld2410b_parse_frame(frame, flen);   /* 一帧收齐 */
325	                }
326	              st = ST_WAIT_HDR;
327	              break;
328	            default:
329	              st = ST_WAIT_HDR;
330	              break;
331	            }
332	        }
333	    }
334	
335	  close(fd);
336	  return NULL;
337	}
